/**
 * TRESORA checkout backend: a Cloudflare Worker that creates Stripe Checkout Sessions.
 *
 * POST /checkout   body: {"items":[{"variant_id":44325276582001,"product_id":7813787385969,"quantity":2}, ...]}
 *                  -> 200 {"url":"https://checkout.stripe.com/c/pay/..."}  (the browser redirects there)
 * GET  /health     -> 200 {"ok":true}
 *
 * Security model
 *  - Prices, names and availability come ONLY from ./catalog.js (generated by tools/build_shop.py), which is bundled at deploy time.
 *    Any price or name the client sends is ignored. Unknown or sold-out variants are rejected.
 *  - Quantities must be integers from 1 to MAX_QTY_PER_LINE, with at most MAX_LINES distinct lines.
 *  - CORS is restricted to ALLOWED_ORIGINS.
 *  - STRIPE_SECRET_KEY is a Worker secret (wrangler secret put). It never appears in code or the repo.
 */
import catalog from "./catalog.js";

const MAX_LINES = 25;
const MAX_QTY_PER_LINE = 20;
const MAX_BODY_BYTES = 10_000;

function corsHeaders(request, env) {
  const origin = request.headers.get("Origin") || "";
  const allowed = (env.ALLOWED_ORIGINS || "").split(",").map((s) => s.trim()).filter(Boolean);
  const h = { "Access-Control-Allow-Methods": "POST, OPTIONS", "Access-Control-Allow-Headers": "Content-Type", "Access-Control-Max-Age": "86400", Vary: "Origin" };
  if (allowed.includes(origin)) h["Access-Control-Allow-Origin"] = origin;
  return h;
}

function json(body, status, headers) {
  return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", ...headers } });
}

/** Validate the client cart against the server catalog. Returns {lines} or {error}. */
export function buildLines(payload, cat = catalog) {
  if (!payload || !Array.isArray(payload.items) || payload.items.length === 0) return { error: "Cart is empty" };
  const merged = new Map();
  for (const item of payload.items) {
    const id = String(item && item.variant_id);
    const qty = item && item.quantity;
    if (!/^\d+$/.test(id)) return { error: "Invalid item" };
    if (!Number.isInteger(qty) || qty < 1 || qty > MAX_QTY_PER_LINE) return { error: "Invalid quantity" };
    const v = cat.variants[id];
    if (!v) return { error: "Unknown product" };
    if (!v.available) return { error: `${v.name} is sold out` };
    if (item.product_id !== undefined && String(item.product_id) !== String(v.product_id)) return { error: "Invalid item" };
    merged.set(id, Math.min(MAX_QTY_PER_LINE, (merged.get(id) || 0) + qty));
  }
  if (merged.size > MAX_LINES) return { error: "Too many items" };
  const lines = [...merged].map(([id, quantity]) => ({ id, quantity, ...cat.variants[id] }));
  return { lines };
}

/** Encode the Stripe Checkout Session parameters as application/x-www-form-urlencoded. */
export function sessionParams(lines, env, currency = catalog.currency || "usd") {
  const site = (env.SITE_URL || "").replace(/\/+$/, "");
  const p = new URLSearchParams();
  p.set("mode", "payment");
  p.set("success_url", `${site}/success.html?session_id={CHECKOUT_SESSION_ID}`);
  p.set("cancel_url", `${site}/cancel.html`);
  p.set("shipping_address_collection[allowed_countries][0]", "US"); // "Free US shipping on all orders"
  p.set("billing_address_collection", "auto");
  if (env.STRIPE_AUTOMATIC_TAX === "true") p.set("automatic_tax[enabled]", "true");
  lines.forEach((l, i) => {
    const k = `line_items[${i}]`;
    p.set(`${k}[quantity]`, String(l.quantity));
    p.set(`${k}[price_data][currency]`, currency);
    p.set(`${k}[price_data][unit_amount]`, String(l.unit_amount));
    p.set(`${k}[price_data][product_data][name]`, l.name);
    if (l.image) p.set(`${k}[price_data][product_data][images][0]`, l.image);
    p.set(`${k}[price_data][product_data][metadata][variant_id]`, l.id);
    p.set(`${k}[price_data][product_data][metadata][product_id]`, String(l.product_id));
  });
  p.set("metadata[cart]", lines.map((l) => `${l.id}x${l.quantity}`).join(",").slice(0, 500));
  return p;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const cors = corsHeaders(request, env);
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    if (url.pathname === "/health") return json({ ok: true }, 200, cors);
    if (url.pathname !== "/checkout" || request.method !== "POST") return json({ error: "Not found" }, 404, cors);
    if (!cors["Access-Control-Allow-Origin"]) return json({ error: "Origin not allowed" }, 403, cors);
    if (!env.STRIPE_SECRET_KEY || !env.SITE_URL) return json({ error: "Checkout is not configured" }, 503, cors);

    const raw = await request.text();
    if (raw.length > MAX_BODY_BYTES) return json({ error: "Request too large" }, 413, cors);
    let payload;
    try { payload = JSON.parse(raw); } catch { return json({ error: "Invalid JSON" }, 400, cors); }

    const { lines, error } = buildLines(payload);
    if (error) return json({ error }, 400, cors);

    const res = await fetch("https://api.stripe.com/v1/checkout/sessions", {
      method: "POST",
      headers: { Authorization: `Bearer ${env.STRIPE_SECRET_KEY}`, "Content-Type": "application/x-www-form-urlencoded", "Stripe-Version": "2024-06-20" },
      body: sessionParams(lines, env),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data.url) {
      console.error("Stripe error", res.status, data && data.error && data.error.message);
      return json({ error: "Payment provider error" }, 502, cors);
    }
    return json({ url: data.url }, 200, cors);
  },
};
